create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,created_at timestamptz default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null,type text not null check(type in('entrada','saida','ambos')),created_at timestamptz default now());
create table if not exists public.accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,type text not null,initial_balance numeric(14,2) default 0,created_at timestamptz default now());
create table if not exists public.cards(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,limit_amount numeric(14,2) default 0,closing_day int check(closing_day between 1 and 31),due_day int check(due_day between 1 and 31),created_at timestamptz default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null check(type in('entrada','saida')),amount numeric(14,2) not null check(amount>0),transaction_date date not null,category_id uuid references public.categories(id) on delete set null,account_id uuid references public.accounts(id) on delete set null,card_id uuid references public.cards(id) on delete set null,status text not null default 'pago' check(status in('pago','pendente')),description text not null,notes text,group_id uuid,installment_number int default 1,installment_total int default 1,created_at timestamptz default now());
create table if not exists public.recurring(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,description text not null,amount numeric(14,2) not null,category_id uuid references public.categories(id) on delete set null,due_day int check(due_day between 1 and 31),start_date date not null,end_date date,created_at timestamptz default now());
create table if not exists public.goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,target_amount numeric(14,2) not null,current_amount numeric(14,2) default 0,deadline date,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1))) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.accounts enable row level security;alter table public.cards enable row level security;alter table public.transactions enable row level security;alter table public.recurring enable row level security;alter table public.goals enable row level security;
create policy "own profiles" on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "own categories" on public.categories for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own accounts" on public.accounts for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own cards" on public.cards for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own transactions" on public.transactions for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own recurring" on public.recurring for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own goals" on public.goals for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create or replace function public.seed_categories(p_user uuid) returns void language sql security definer set search_path=public as $$ insert into public.categories(user_id,name,type) values
(p_user,'Salário','entrada'),(p_user,'Extra','entrada'),(p_user,'Reembolso','entrada'),(p_user,'Outros recebimentos','entrada'),(p_user,'Casa','saida'),(p_user,'Mercado','saida'),(p_user,'Alimentação','saida'),(p_user,'Carro','saida'),(p_user,'Combustível','saida'),(p_user,'Contas','saida'),(p_user,'Celular/Internet','saida'),(p_user,'Cartão','saida'),(p_user,'Lazer','saida'),(p_user,'Compras','saida'),(p_user,'Pets','saida'),(p_user,'Família','saida'),(p_user,'Investimentos','saida'),(p_user,'Outros','saida'); $$;
-- Depois de criar sua conta: select public.seed_categories('SEU_UUID');
